style.css:
@-moz-document domain("roblox.com") {
body {
        background-color: #4B0082 !important; /* Fondo morado oscuro */
        color: white !important;
        cursor: url('https://cur.cursors-4u.net/cursors/cur-2/cur124.cur'), auto !important; /* Cursor personalizado */
    }

    .container, .content, .profile-container, .game-container {
        background-color: #6A0DAD !important; /* Morado intermedio */
        border-radius: 10px !important;
        padding: 15px !important;
    }

    .navbar, .topbar {
        background-color: #8A2BE2 !important; /* Morado vibrante */
    }

    a, button {
        color: #FFD700 !important; /* Amarillo dorado para contraste */
    }

    a:hover, button:hover {
        color: #FF69B4 !important; /* Rosado vibrante al pasar el cursor */
    }

    /* Imagen de fondo de Kuromi */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: url('https://i.imgur.com/JlRRT0p.png') no-repeat center center fixed;
        background-size: cover;
        opacity: 0.3; /* Para que no opaque el contenido */
        z-index: -1;
    }
}
